    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_WAREHOUSE" PRIMARY KEY ("WAREHOUSE_ID"),
    CONSTRAINT "FK_WAREHOUSE_COUNTRY" FOREIGN KEY ("COUNTRY_ISO3") REFERENCES "COUNTRY" ("ISO3"),
    CONSTRAINT "FK_WAREHOUSE_NEAREST_PORT" FOREIGN KEY ("NEAREST_PORT_ID") REFERENCES "PORT" ("PORT_ID"),
    CONSTRAINT "CK_WAREHOUSE_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED'))
);

