    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_SUPPLIER_PRODUCT" PRIMARY KEY ("SUPPLIER_ID", "PRODUCT_ID"),
    CONSTRAINT "FK_SUPPLIER_PRODUCT_SUPPLIER" FOREIGN KEY ("SUPPLIER_ID") REFERENCES "SUPPLIER" ("SUPPLIER_ID"),
    CONSTRAINT "FK_SUPPLIER_PRODUCT_PRODUCT" FOREIGN KEY ("PRODUCT_ID") REFERENCES "PRODUCT" ("PRODUCT_ID"),
    CONSTRAINT "CK_SUPPLIER_PRODUCT_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED')),
    CONSTRAINT "CK_SUPPLIER_PRODUCT_CAPACITY" CHECK ("CAPACITY" > 0),
    CONSTRAINT "CK_SUPPLIER_PRODUCT_UNIT_COST" CHECK ("UNIT_COST" > 0),
    CONSTRAINT "CK_SUPPLIER_PRODUCT_LEAD_TIME" CHECK ("LEAD_TIME_DAYS" >= 0),
    CONSTRAINT "CK_SUPPLIER_PRODUCT_RELIABILITY" CHECK ("RELIABILITY" BETWEEN 0 AND 1)
);

