    CONSTRAINT "CK_ROUTE_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED')),
    CONSTRAINT "CK_ROUTE_TRANSPORT_MODE" CHECK ("TRANSPORT_MODE" IN ('sea', 'rail', 'air')),
    CONSTRAINT "CK_ROUTE_LANE_ROLE" CHECK ("LANE_ROLE" IN ('PRIMARY', 'ALTERNATIVE')),
    CONSTRAINT "CK_ROUTE_DISTANCE" CHECK ("DISTANCE_KM" > 0),
