    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_TARIFF" PRIMARY KEY ("ORIGIN_ISO3", "DEST_ISO3", "HS_SECTION", "EFFECTIVE_YEAR"),
    CONSTRAINT "FK_TARIFF_COUNTRY" FOREIGN KEY ("ORIGIN_ISO3") REFERENCES "COUNTRY" ("ISO3"),
    CONSTRAINT "CK_TARIFF_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED')),
    CONSTRAINT "CK_TARIFF_RATE" CHECK ("TARIFF_RATE_PCT" >= 0),
    CONSTRAINT "CK_TARIFF_YEAR" CHECK ("EFFECTIVE_YEAR" BETWEEN 1960 AND 2100)
);

CREATE COLUMN TABLE "DISRUPTION_EVENT" (
