    CONSTRAINT "CK_DISRUPTION_EVENT_SEVERITY" CHECK ("SEVERITY" IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT "CK_DISRUPTION_EVENT_STATUS" CHECK ("STATUS" IN ('ACTIVE', 'RESOLVED', 'HISTORICAL')),
    CONSTRAINT "CK_DISRUPTION_EVENT_VERIFICATION" CHECK ("VERIFICATION_STATUS" IN ('UNVERIFIED_IN_WORKSPACE', 'CORROBORATED_BY_WDI', 'NOT_CORROBORATED_BY_WDI')),
    CONSTRAINT "CK_DISRUPTION_EVENT_PERIOD" CHECK ("END_TS" IS NULL OR "END_TS" >= "START_TS"),
