);

CREATE COLUMN TABLE "INVENTORY_POLICY" (
    "WAREHOUSE_ID" NVARCHAR(32) NOT NULL,
    "DEMAND_SHARE" DECIMAL(5,4) NOT NULL,
    "COVER_MULTIPLIER" DECIMAL(6,4) NOT NULL,
    "SAFETY_MULTIPLIER" DECIMAL(6,4) NOT NULL,
    "TARGET_DAYS_OF_COVER" INTEGER NOT NULL,
    "SAFETY_DAYS" INTEGER NOT NULL,
    "REPLENISH_DAYS" INTEGER NOT NULL,
    "REPLENISHMENT_LEAD_TIME_DAYS" INTEGER NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_INVENTORY_POLICY" PRIMARY KEY ("WAREHOUSE_ID"),
    CONSTRAINT "FK_INVENTORY_POLICY_WAREHOUSE" FOREIGN KEY ("WAREHOUSE_ID") REFERENCES "WAREHOUSE" ("WAREHOUSE_ID"),
    CONSTRAINT "CK_INVENTORY_POLICY_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED')),
    CONSTRAINT "CK_INVENTORY_POLICY_DEMAND_SHARE" CHECK ("DEMAND_SHARE" BETWEEN 0 AND 1),
    CONSTRAINT "CK_INVENTORY_POLICY_MULTIPLIERS" CHECK ("COVER_MULTIPLIER" > 0 AND "SAFETY_MULTIPLIER" > 0),
    CONSTRAINT "CK_INVENTORY_POLICY_DAYS" CHECK ("TARGET_DAYS_OF_COVER" >= 0 AND "SAFETY_DAYS" >= 0 AND "REPLENISH_DAYS" >= 0 AND "REPLENISHMENT_LEAD_TIME_DAYS" >= 0)
);

CREATE COLUMN TABLE "INVENTORY" (
    "WAREHOUSE_ID" NVARCHAR(32) NOT NULL,
    "PRODUCT_ID" NVARCHAR(32) NOT NULL,
    "DATE" DATE NOT NULL,
    "OPENING_STOCK" INTEGER NOT NULL,
    "INBOUND_QUANTITY" INTEGER NOT NULL,
    "OUTBOUND_QUANTITY" INTEGER NOT NULL,
    "CLOSING_STOCK" INTEGER NOT NULL,
    "SAFETY_STOCK" INTEGER NOT NULL,
    "REORDER_POINT" INTEGER NOT NULL,
    "DEMAND_QUANTITY" INTEGER NOT NULL,
    "UNFILLED_QUANTITY" INTEGER NOT NULL,
    "STOCKOUT_FLAG" BOOLEAN NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_INVENTORY" PRIMARY KEY ("WAREHOUSE_ID", "PRODUCT_ID", "DATE"),
    CONSTRAINT "FK_INVENTORY_WAREHOUSE" FOREIGN KEY ("WAREHOUSE_ID") REFERENCES "WAREHOUSE" ("WAREHOUSE_ID"),
    CONSTRAINT "FK_INVENTORY_PRODUCT" FOREIGN KEY ("PRODUCT_ID") REFERENCES "PRODUCT" ("PRODUCT_ID"),
    CONSTRAINT "CK_INVENTORY_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED')),
    CONSTRAINT "CK_INVENTORY_QUANTITIES" CHECK ("OPENING_STOCK" >= 0 AND "INBOUND_QUANTITY" >= 0 AND "OUTBOUND_QUANTITY" >= 0 AND "CLOSING_STOCK" >= 0 AND "SAFETY_STOCK" >= 0 AND "REORDER_POINT" >= 0 AND "DEMAND_QUANTITY" >= 0 AND "UNFILLED_QUANTITY" >= 0)
);

CREATE COLUMN TABLE "DEMAND" (
    "DATE" DATE NOT NULL,
    "PRODUCT_ID" NVARCHAR(32) NOT NULL,
    "LOCATION_ID" NVARCHAR(64) NOT NULL,
    "COUNTRY_ISO3" NVARCHAR(3) NOT NULL,
    "DEMAND_QUANTITY" INTEGER NOT NULL,
    "N_ORDER_LINES" INTEGER NOT NULL,
    "N_OUTLIER_LINES" INTEGER NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_DEMAND" PRIMARY KEY ("DATE", "PRODUCT_ID", "LOCATION_ID"),
    CONSTRAINT "FK_DEMAND_PRODUCT" FOREIGN KEY ("PRODUCT_ID") REFERENCES "PRODUCT" ("PRODUCT_ID"),
    CONSTRAINT "FK_DEMAND_COUNTRY" FOREIGN KEY ("COUNTRY_ISO3") REFERENCES "COUNTRY" ("ISO3"),
    CONSTRAINT "CK_DEMAND_PROVENANCE" CHECK ("PROVENANCE" IN ('REAL', 'DERIVED', 'SYNTHETIC', 'AUTHORED')),
    CONSTRAINT "CK_DEMAND_QUANTITY" CHECK ("DEMAND_QUANTITY" > 0),
    CONSTRAINT "CK_DEMAND_LINES" CHECK ("N_ORDER_LINES" > 0 AND "N_OUTLIER_LINES" >= 0)
);

